section.sourcecode:
window.opener.postMessage(
  {
    code: "ABC",
    state: "123"
  },
  "*" // オープナーウィンドウ内のどのWebサイトもメッセージを受信できる
)

window.opener.postMessage(
  {
    code: "ABC",
    state: "123"
  },
  "https://attacker.example" // 攻撃者が指定した値
)

window.opener.postMessage(
  {
    code: "ABC",
    state: "123"
  },
  "https://client.example" // 明示的なクライアントのオリジンを使う
)

window.addEventListener("message", (e) => {
  // 認可サーバーのオリジンと完全に一致するか検証する
  if (e.origin === "https://honest.as.example") {
    // e.data.code と e.data.state を処理する
  }
})
